const __pageData = JSON.parse('{"title":"LLM 工具调用工程实践：Schema 契约、执行边界与失败恢复","description":"","frontmatter":{"title":"LLM 工具调用工程实践：Schema 契约、执行边界与失败恢复","date":"2026-08-13T00:00:00.000Z","category":"AI","cover":"/covers/backend.svg","tags":["llm","tool-calling","spring-ai","json-schema","agent"],"excerpt":"从模型只负责提出调用请求这一边界出发，讲清工具定义、JSON Schema、应用侧执行、权限与幂等、结果回传、失败恢复和可观测性，并给出 Spring AI 2.0.0 的订单售后示例。"},"headers":[],"relativePath":"posts/llm-tool-calling-contract-engineering.md","filePath":"posts/llm-tool-calling-contract-engineering.md","lastUpdated":1787128073000}');
